REPLACE INTO `om_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (26999,10,'2026-08-20 15:40:37','2026-08-20 12:40:37','document.addEventListener(\'DOMContentLoaded\', function () {\r\n\r\n    const items = [\r\n        { section: \'info-1\', nav: \'nav-info-1\' },\r\n        { section: \'info-2\', nav: \'nav-info-2\' },\r\n        { section: \'info-3\', nav: \'nav-info-3\' },\r\n        { section: \'info-4\', nav: \'nav-info-4\' }\r\n    ];\r\n\r\n    const validItems = items\r\n        .map(item => ({\r\n            section: document.getElementById(item.section),\r\n            nav: document.getElementById(item.nav)\r\n        }))\r\n        .filter(item => item.section && item.nav);\r\n\r\n    if (!validItems.length) return;\r\n\r\n    function updateActiveItem() {\r\n        let activeItem = validItems[0];\r\n        const triggerPoint = 220;\r\n\r\n        validItems.forEach(item => {\r\n            const rect = item.section.getBoundingClientRect();\r\n\r\n            if (rect.top <= triggerPoint) {\r\n                activeItem = item;\r\n            }\r\n        });\r\n\r\n        validItems.forEach(item => {\r\n            item.nav.classList.toggle(\r\n                \'about-active\',\r\n                item === activeItem\r\n            );\r\n        });\r\n    }\r\n\r\n    window.addEventListener(\'scroll\', updateActiveItem, { passive: true });\r\n    updateActiveItem();\r\n});','Information Center Sidebar Active Row','','publish','closed','closed','','information-center-sidebar-active-row','','','2026-08-20 15:40:37','2026-08-20 12:40:37','',0,'http://localhost/idal/wpcode/information-center-sidebar-active-row/',0,'wpcode','',0);
